// Android, шаг 2 «כוונו את המצלמה לבריכה»: галочки «זו הבריכה שלי» и сообщения «בהירים מהרגיל» нет; есть «כל שטח המים נראה…».
// Маркер того, что OTA c38476a1 загрузился. Сцена не нужна. Шаг 1 может просить громкий тестовый звук → BANCI_SOUND=1 (иначе пропуск).
import { assert, openCameraStep, OLD_POOL_CHECKBOX, PALE_HINT } from '../lib.mjs';

export const name = 'Android шаг 2: нет галочки «זו הבריכה שלי» и «בהירים מהרגיל»; есть «כל שטח המים נראה…» (любая сцена; шаг 1 → BANCI_SOUND=1) #ab4270 @android @app';

export default async function (app) {
  await openCameraStep(app);
  assert(!(await app.exists(OLD_POOL_CHECKBOX)), 'нет галочки «זו הבריכה שלי» (если есть — OTA c38476a1 не загрузился: закрыть/открыть Eitan 2 раза)');
  assert(!(await app.exists(PALE_HINT)), 'нет сообщения «בהירים מהרגיל»');
  await app.screenshot('ab4270-step2-no-pool-confirm-checkbox');
  await app.restart();
}
